import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.DiAOIirN.js";var i=JSON.parse(`{"title":"Flows","description":"","frontmatter":{},"headers":[],"relativePath":"patterns/flows.md","filePath":"patterns/flows.md","lastUpdated":1700347417000}`),a={name:`patterns/flows.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="flows" tabindex="-1">Flows <a class="header-anchor" href="#flows" aria-label="Permalink to “Flows”">​</a></h1><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>The following pattern, although still useful, has been mostly super-seeded by the new <a href="./../guide/flows/">Flows</a> functionality</p></div><p>In some situations, you may need to execute a flow of several actions, any of which could fail. For example, you may need to update a database, make calls to external services, or any other kind of asynchronous call.</p><p>Sometimes it may not be possible to create an <a href="./idempotent-jobs">idempotent job</a> that can execute all these actions again in the case one of them failed for any reason. Instead, we may want to be able to only re-execute the action that failed and continue executing the rest of the actions that have not yet been executed.</p><p>The pattern to solve this issue consists of dividing the flow of actions into one queue for every action. When the first action completes, it places the next action as a job in its corresponding queue.</p>`,5)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};